#define debugArr(...) std::cerr << __LINE__ << ": [", __DEBUG_UTIL__::printerArr(#__VA_ARGS__, __VA_ARGS__)
#else
#define debug(...)
#define debugArr(...)
#endif
//#pragma GCC optimize("trapv")
static const int MAXN = 100005;
static const int MAXK = 55;

int n, k;
int a[MAXN+1];
long long dp_prev[MAXN+1], dp_cur[MAXN+1];

long long freq[MAXN+1];
int curr_l = 1, curr_r = 0;
long long curr_cost = 0;

long long calc_(long long n) {
    return n * (n - 1) / 2;
}

inline void add(int x) {
    int t = a[x];
    curr_cost -= calc_(freq[t]);
    freq[t]++;
    curr_cost += calc_(freq[t]);
}

inline void remove_(int x) {
    int t = a[x];
    curr_cost -= calc_(freq[t]);
    freq[t]--;
    curr_cost += calc_(freq[t]);
}

void go_to(int l, int r) {
    while (curr_r < r) add(++curr_r);
    while (curr_r > r) remove_(curr_r--);
    while (curr_l < l) remove_(curr_l++);
    while (curr_l > l) add(--curr_l);
}

void compute(int d, int L, int R, int optL, int optR) {
    if (L > R) return;
    int mid = (L + R) >> 1;
    long long best_val = 1e18;
    int best_k = optL;

    int end = min(mid-1, optR);
    for (int j = optL; j <= end; ++j) {
        go_to(j+1, mid);
        long long val = dp_prev[j] + curr_cost;
        if (val < best_val) {
            best_val = val;
            best_k = j;
        }
    }
    dp_cur[mid] = best_val;

    compute(d, L, mid-1, optL, best_k);
    compute(d, mid+1, R, best_k, optR);
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> n >> k;
    for (int i = 1; i <= n; ++i)
        cin >> a[i];

    dp_prev[0] = 0;
    for (int i = 1; i <= n; ++i)
        dp_prev[i] = 1e18;

    for (int d = 1; d <= k; ++d) {

        memset(freq, 0, sizeof(freq));
        curr_l = 1; curr_r = 0; curr_cost = 0;

        dp_cur[0] = 1e18;
        compute(d, 1, n, 0, n-1);

        swap(dp_prev, dp_cur);
    }

    cout << dp_prev[n] << "\n";
}